// 1) Valida el secreto compartido (mismo valor que credentials.secret de la
//    integración n8n en la app).
const item = $input.first().json;
const secret = (item.headers && item.headers['x-agent-secret']) || '';
const EXPECTED = $env.AGENT_SECRET || 'CAMBIA_ESTE_SECRETO';
if (secret !== EXPECTED) {
  throw new Error('Secret inválido');
}

const body = item.body || {};
const history = Array.isArray(body.history) ? body.history : [];
const media = Array.isArray(body.media) ? body.media : [];

// 2) MEDIA (voz/imagen): este scaffold es text-first. Si media.length > 0,
//    agrega ANTES de este nodo (o en un branch) la descarga de media[i].signed_url
//    y su transcripción (Whisper) / visión, y súmalo a mergedText.
let mediaNote = '';
if (media.length) {
  mediaNote = '\n[El cliente envió ' + media.length + ' archivo(s) multimedia; ' +
    'signed_url disponibles para transcribir/entender.]';
}

// 3) Arma los mensajes para el LLM.
const messages = [
  {
    role: 'system',
    content: 'Eres el asistente de WhatsApp de un concesionario. Tu trabajo es calificar leads: identifica modelo de interés, presupuesto y forma de pago, y responde breve, cálido y claro en español colombiano. Si el lead está listo para avanzar, dilo.'
  },
  ...history.map(h => ({
    role: h.role === 'assistant' ? 'assistant' : 'user',
    content: String(h.content || '')
  })),
  { role: 'user', content: String(body.mergedText || '') + mediaNote }
];

return [{ json: { messages, _ctx: { workspaceId: body.workspaceId, conversationId: body.conversationId } } }];

// Extrae la respuesta y la devuelve en el contrato que espera la app:
//   { text: string, actions?: [{ type: 'handoff'|'add_tag'|'send_template'|'set_stage', ... }] }
const data = $input.first().json;
const text = (data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content || '').trim()
  || 'Gracias por tu mensaje, en un momento te atiende un asesor.';

// Ejemplo de acción (opcional): descomenta para probar el handoff.
// const actions = [{ type: 'handoff' }];
const actions = [];

return [{ json: { text, actions } }];
